function pile(cx,cz,r){return [...layer(cx,cz,r+1,r,1,GOLD,true),...layer(cx,cz,r,Math.max(1,r-1),2,GOLD,true),...layer(cx,cz,Math.max(1,r-1),1,3,GOLD,false)];}
