 ...layer(0,2,17,14,0,ROCK,true),
 ...layer(0,2,14,11,1,GOLD,true),
 ...layer(1,3,10,8,2,GOLD,true),
 ...pile(-12,-7,2),...pile(12,7,2),...pile(-12,8,3),...pile(11,-8,2)
]);
const sx=(x0,w)=>[x0,-x0-w];
function legs(){const ops=[];
 for(const s of [0,1]){
  const X=(x0,w)=>sx(x0,w)[s];
  ops.push(B(X(-5,2),3,-7,2,7,2,R));
  ops.push(B(X(-6,3),1,-10,3,2,4,R));
  for(const cx of [-6,-5,-4]) ops.push(place({part:'15070',at:[s?-1-cx:cx,3,-10],colour:'white'}));
  ops.push(B(X(-7,3),3,1,3,10,7,R));
  for(const z of [1,3,5]) ops.push(place({part:'15068',at:[X(-7,2),13,z],colour:R,turn:s?270:90}));
  ops.push(B(X(-8,3),1,-2,3,2,4,R));
  for(const cx of [-8,-7,-6]) ops.push(place({part:'15070',at:[s?-1-cx:cx,3,-2],colour:'white'}));
 }
 return ops;}
section('Body',[
 B(-5,8,-6,10,9,16,R,{interior:'empty',top:'tile'}),
 B(-3,17,-5,6,3,13,R,{top:'tile'}),
