 B(-2,0,15,4,6,4,R,{top:'tile'}),
 B(1,0,17,4,5,3,R,{top:'tile'}),
 B(4,0,16,4,4,3,R,{top:'tile'}),
 B(7,0,14,3,4,3,R,{top:'tile'}),
 place({part:'3040b',at:[-1,16,10],colour:DR,turn:180}),
 place({part:'3040b',at:[-1,12,13],colour:DR,turn:180}),
 place({part:'3040b',at:[-1,6,16],colour:DR,turn:180}),
 place({part:'3040b',at:[2,5,18],colour:DR,turn:270}),
 place({part:'3040b',at:[5,4,17],colour:DR,turn:270}),
 place({part:'3039',at:[7,4,14],colour:DR,turn:0})
]);
