 place({part:'98138',at:[1,38,-20],colour:'black'}),
 B(-2,30,-19,4,2,4,R),
 ...[[-2,-19],[1,-19],[-2,-17],[1,-17]].map(p=>place({part:'15070',at:[p[0],32,p[1]],colour:'white'}))
]);
const FIRE={mix:['trans red','trans yellow','trans red']};
const fire=[B(-1,32,-19,2,3,4,'trans yellow')];
for(let k=0;k<12;k++){let yb=32-3*k,h=3;if(yb<0){h+=yb;yb=0;}fire.push(B(-1-k,yb,-21-k,2,h,2,FIRE));}
section('Dragonfire',[...fire,
