function segDist(px,py,ax,ay,bx,by){const dx=bx-ax,dy=by-ay;let t=((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy);t=Math.max(0,Math.min(1,t));const qx=ax+t*dx-px,qy=ay+t*dy-py;return Math.sqrt(qx*qx+qy*qy);}
const BOT=[9,12,15,18,18,15,18,21,24,24,21,18,21,24,24,24,21,24,24,24];
const TOP=u=>u<10?24+3*Math.floor(u/2):(u<12?39:36-3*Math.floor((u-12)/2));
const FING=[[5,15],[11,18],[16,21],[19.5,24]];
function wcol(u,y){if(y+3>=TOP(u))return R;const py=(y+1.5)/2.5,px=u+0.5;for(const f of FING){if(segDist(px,py,10.5,37/2.5,f[0],f[1]/2.5)<0.7)return R;}return DR;}
const zone=u=>u<10?0:(u<12?1:2);
const ZZ=[[-5,2],[-5,3],[-4,2]];
function wing(side,dy){const ops=[];const xo=u=>side<0?-6-u:5+u;const has=(u,y)=>y>=BOT[u]&&y<TOP(u);
 for(let y=9;y<39;y+=3){let u=0;while(u<20){if(!has(u,y)){u++;continue;}const c=wcol(u,y),zn=zone(u);let v=u;while(v+1<20&&has(v+1,y)&&wcol(v+1,y)===c&&zone(v+1)===zn)v++;ops.push(B(Math.min(xo(u),xo(v)),y+dy,ZZ[zn][0],v-u+1,3,ZZ[zn][1],c));u=v+1;}}
 for(let p=0;p<10;p++){if(p===5)continue;const u=2*p;const x=Math.min(xo(u),xo(u+1));const lead=p<5;const turn=side<0?(lead?270:90):(lead?90:270);ops.push(place({part:'3039',at:[x,TOP(u)+dy,lead?-5:-4],colour:R,turn}));}
 ops.push(place({part:'3062b',at:[xo(10),39+dy,-4],colour:R}));
 ops.push(place({part:'4589',at:[xo(10),42+dy,-4],colour:'white'}));
 return ops;}
